import {Component, OnInit, OnDestroy} from '@angular/core';
import {CommonModule} from '@angular/common';
import {ReactiveFormsModule, FormBuilder, FormGroup, Validators, FormsModule} from '@angular/forms';
import { HttpClient } from '@angular/common/http'; // Import HttpClient
import {CartService} from '../services/cart.service'; // Import CartService
import {Observable, Subscription} from 'rxjs'; // Import Observable and Subscription
import {RouterModule} from '@angular/router'; // Import RouterModule
import {CartItem} from '../models/cart.model'; // Import CartItem
import { AuthService } from '../services/auth.service'; // Import AuthService

@Component({
    selector: 'app-checkout',
    standalone: true,
    imports: [CommonModule, ReactiveFormsModule, FormsModule, RouterModule], // Add RouterModule here
    templateUrl: './checkout.component.html',
    styleUrls: ['./checkout.component.css']
})
export class CheckoutComponent implements OnInit, OnDestroy {
    checkoutForm: FormGroup;
    selectedPaymentMethod = 'creditCard';
    discountCode: string = '';
    discountMessage: string = '';
    discountAmount: number = 0;
    discountAppliedSuccessfully: boolean = false;
    userEmail: string | null = null; // Added to store user's email

    cartItems: CartItem[] = []; // Will hold cart items // Changed from any[] to CartItem[]
    private cartSubscription: Subscription | undefined;

    shippingAndHandling: number = 0; // Assuming a fixed shipping cost, 0 as per image
    estimatedTaxRate: number = 0.10; // 10% tax rate, matches image and cart service

    itemsTotal: number = 0;
    totalBeforeTax: number = 0;
    estimatedTax: number = 0;
    orderTotal: number = 0;

    private readonly SHIPPING_ADDRESS_KEY = 'shippingAddress';
    private readonly SAVE_ADDRESS_PREFERENCE_KEY = 'saveAddressPreference';

    constructor(
        private formBuilder: FormBuilder,
        private cartService: CartService, // Inject CartService
        private authService: AuthService, // Inject AuthService
        private http: HttpClient // Inject HttpClient
    ) {
        this.checkoutForm = this.formBuilder.group({
            // Contact & Shipping
            email: ['', [Validators.required, Validators.email]],
            newsletter: [false],
            firstName: ['', Validators.required],
            lastName: ['', Validators.required],
            address: ['', Validators.required],
            apartment: [''],
            city: ['', Validators.required],
            country: ['United States', Validators.required],
            state: ['', Validators.required],
            zipCode: ['', Validators.required],
            phone: [''],
            saveAddress: [true],

            // Payment
            paymentMethod: ['creditCard'],
            cardNumber: ['', Validators.required],
            expirationDate: ['', Validators.required],
            cvv: ['', Validators.required],
            nameOnCard: ['', Validators.required],
            saveCard: [false]
            // Removed discountCode from here as it's handled separately
        });
    }    ngOnInit(): void {
        // Subscribe to cart items from the CartService
        this.cartSubscription = this.cartService.cartItems$.subscribe((items: CartItem[]) => {
            this.cartItems = items;
            this.calculateTotals();
        });
        if (this.authService.isLoggedIn && this.authService.currentUserValue) {
            this.userEmail = this.authService.currentUserValue.email;
            this.checkoutForm.patchValue({ email: this.userEmail });
        }

        this.loadSavedAddress();
    }

    ngOnDestroy(): void {
        if (this.cartSubscription) {
            this.cartSubscription.unsubscribe();
        }
    }    calculateTotals(): void {
        // Calculate totals directly from cart items
        this.itemsTotal = this.cartItems.reduce((total, item) => {
            // Convert price string to number if needed
            const price = typeof item.product.price === 'string' 
                ? parseFloat(item.product.price.replace(/[^\d.]/g, '')) 
                : parseFloat(item.product.price);
            return total + (price * item.quantity);
        }, 0);

        this.estimatedTax = this.itemsTotal * this.estimatedTaxRate;
        this.totalBeforeTax = this.itemsTotal + this.shippingAndHandling - this.discountAmount;
        this.orderTotal = this.totalBeforeTax + this.estimatedTax;
    }

    getItemCount(): number {
        return this.cartItems.reduce((sum, item) => sum + item.quantity, 0);
    }

    // Added methods to handle cart item manipulations
    incrementItem(item: CartItem): void {
        this.cartService.incrementItem(item);
        // calculateTotals() is called via the cartItems$ subscription
    }

    decrementItem(item: CartItem): void {
        this.cartService.decrementItem(item);
        // calculateTotals() is called via the cartItems$ subscription
    }

    removeItem(item: CartItem): void {
        this.cartService.removeItem(item);
        // calculateTotals() is called via the cartItems$ subscription
    }

    applyDiscount(): void {
        if (this.discountCode.toUpperCase() === 'WELCOME10') {
            this.discountAmount = 10.00;
            this.discountMessage = `You've saved $10.00 with the "WELCOME10" discount!`;
            this.discountAppliedSuccessfully = true;
        } else if (this.discountCode.trim() === '') {
            this.discountMessage = 'Please enter a discount code.';
            this.discountAppliedSuccessfully = false;
            this.discountAmount = 0; // Reset discount if code is empty
        } else {
            this.discountAmount = 0;
            this.discountMessage = 'Invalid discount code. Please try again.';
            this.discountAppliedSuccessfully = false;
        }
        this.calculateTotals(); // Recalculate after applying/failing discount
    }

    onPaymentMethodChange(method: string) {
        this.selectedPaymentMethod = method;
        this.checkoutForm.patchValue({paymentMethod: method});
    }

    onSubmit() {
        if (this.checkoutForm.valid) {
            console.log('Form submitted:', this.checkoutForm.value);
            // Handle form submission here

            if (this.checkoutForm.get('saveAddress')?.value) {
                const shippingAddress = {
                    firstName: this.checkoutForm.get('firstName')?.value,
                    lastName: this.checkoutForm.get('lastName')?.value,
                    address: this.checkoutForm.get('address')?.value,
                    apartment: this.checkoutForm.get('apartment')?.value,
                    city: this.checkoutForm.get('city')?.value,
                    country: this.checkoutForm.get('country')?.value,
                    state: this.checkoutForm.get('state')?.value,
                    zipCode: this.checkoutForm.get('zipCode')?.value,
                    phone: this.checkoutForm.get('phone')?.value
                };
                localStorage.setItem(this.SHIPPING_ADDRESS_KEY, JSON.stringify(shippingAddress));
                localStorage.setItem(this.SAVE_ADDRESS_PREFERENCE_KEY, 'true');
            } else {
                localStorage.removeItem(this.SHIPPING_ADDRESS_KEY);
                localStorage.setItem(this.SAVE_ADDRESS_PREFERENCE_KEY, 'false');
            }

            // Call payment API
            const email = this.checkoutForm.get('email')?.value;
            const amount = this.orderTotal;
            const currency = 'VND'; // Or get from a config or service

            // It looks like the API endpoint in the prompt is incomplete.
            // Assuming it should be something like: http://localhost:7070/api/payment/invoice
            // And the parameters are query parameters.
            const apiUrl = `http://localhost:7070/api/payment/invoice?email=${email}&amount=${amount}&currency=${currency}`;

            this.http.post(apiUrl, {}).subscribe({
                next: (response) => {
                    console.log('Payment successful', response);
                    // Handle successful payment (e.g., navigate to order confirmation page)
                },
                error: (error) => {
                    console.error('Payment failed', error);
                    // Handle payment error (e.g., show error message to user)
                }
            });


        } else {
            console.log('Form is invalid');
            this.markFormGroupTouched();
        }
    }

    private markFormGroupTouched() {
        Object.keys(this.checkoutForm.controls).forEach(key => {
            const control = this.checkoutForm.get(key);
            control?.markAsTouched();
        });
    }

    isFieldInvalid(fieldName: string): boolean {
        const field = this.checkoutForm.get(fieldName);
        return !!(field && field.invalid && field.touched);
    }

    private loadSavedAddress(): void {
        const savedAddressPreference = localStorage.getItem(this.SAVE_ADDRESS_PREFERENCE_KEY);
        if (savedAddressPreference === 'true') {
            this.checkoutForm.get('saveAddress')?.setValue(true);
            const savedAddress = localStorage.getItem(this.SHIPPING_ADDRESS_KEY);
            if (savedAddress) {
                try {
                    const addressData = JSON.parse(savedAddress);
                    this.checkoutForm.patchValue({
                        firstName: addressData.firstName,
                        lastName: addressData.lastName,
                        address: addressData.address,
                        apartment: addressData.apartment,
                        city: addressData.city,
                        country: addressData.country,
                        state: addressData.state,
                        zipCode: addressData.zipCode,
                        phone: addressData.phone
                    });
                } catch (e) {
                    console.error('Error parsing saved shipping address:', e);
                    localStorage.removeItem(this.SHIPPING_ADDRESS_KEY); // Clear corrupted data
                    localStorage.removeItem(this.SAVE_ADDRESS_PREFERENCE_KEY);
                }
            }
        } else {
             this.checkoutForm.get('saveAddress')?.setValue(false); // Default to false if no preference
        }
    }

    getFieldError(fieldName: string): string {
        const field = this.checkoutForm.get(fieldName);
        if (field?.errors) {
            if (field.errors['required']) return `Please enter your ${fieldName}.`;
            if (field.errors['email']) return 'Please enter a valid email address.';
        }
        return '';
    }
}
<!-- Main Content -->
<main class="flex flex-1 justify-center py-10 sm:py-16 w-full overflow-x-hidden">
    <div class="flex flex-col lg:flex-row items-start gap-10 w-full">

        <!-- Checkout Form -->
        <form [formGroup]="checkoutForm" (ngSubmit)="onSubmit()" class="w-full lg:w-3/5 space-y-10">

            <!-- Contact & Shipping Section -->
            <section class="section-card space-y-8 relative">
                <div class="absolute -top-4 -left-4 w-16 h-16 bg-[#eb6c28]/30 rounded-full opacity-50 blur-xl -z-10 animate-pulse"></div>

                <div class="flex justify-between items-center mb-6">
                    <h2 class="title-text text-[#1b120e] text-2xl font-bold leading-tight flex items-center gap-2.5">
                        <span class="material-icons-outlined text-3xl text-[#eb6c28]">person_outline</span>
                        Contact & Shipping
                    </h2>
                </div>

                <!-- Email -->
                <div>
                    <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="email">Email Address</label>
                    <div class="relative">
                        <input
                                class="input-field pl-12 border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                [class.input-error]="isFieldInvalid('email')"
                                id="email"
                                formControlName="email"
                                placeholder="you@example.com"
                                type="email"
                        />
                        <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">email</span>
                    </div>
                    <p class="error-message" [class.hidden]="!isFieldInvalid('email')">
                        {{ getFieldError('email') }}
                    </p>
                </div>

                <!-- Newsletter Checkbox -->
                <div class="flex items-center gap-3 mt-5">
                    <input
                            class="form-checkbox h-5 w-5 text-[#eb6c28] border-[#f3ebe7] rounded focus:ring-[#eb6c28] transition-colors"
                            id="newsletter"
                            formControlName="newsletter"
                            type="checkbox"
                    />
                    <label class="text-base text-[#1b120e]" for="newsletter">Email me with news and offers</label>
                </div>

                <!-- Shipping Address -->
                <div class="mt-10 pt-10 border-t border-[#f3ebe7]">
                    <h3 class="title-text text-[#1b120e] text-xl font-semibold leading-tight mb-6 flex items-center gap-2.5">
                        <span class="material-icons-outlined text-2xl text-[#eb6c28]">local_shipping</span>
                        Shipping Address
                    </h3>

                    <div class="grid grid-cols-1 gap-y-7">
                        <!-- First Name & Last Name -->
                        <div class="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-7">
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="first-name">First
                                    Name</label>
                                <input
                                        class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('firstName')"
                                        id="first-name"
                                        formControlName="firstName"
                                        placeholder="John"
                                />
                                <p class="error-message" [class.hidden]="!isFieldInvalid('firstName')">
                                    {{ getFieldError('firstName') }}
                                </p>
                            </div>
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="last-name">Last
                                    Name</label>
                                <input
                                        class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('lastName')"
                                        id="last-name"
                                        formControlName="lastName"
                                        placeholder="Doe"
                                />
                                <p class="error-message" [class.hidden]="!isFieldInvalid('lastName')">
                                    {{ getFieldError('lastName') }}
                                </p>
                            </div>
                        </div>

                        <!-- Address -->
                        <div>
                            <label class="block text-base font-medium text-[#1b120e] pb-2.5"
                                   for="address">Address</label>
                            <div class="relative">
                                <input
                                        class="input-field pl-12 w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('address')"
                                        id="address"
                                        formControlName="address"
                                        placeholder="123 Main St"
                                />
                                <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">home</span>
                            </div>
                            <p class="error-message" [class.hidden]="!isFieldInvalid('address')">
                                {{ getFieldError('address') }}
                            </p>
                        </div>

                        <!-- Apartment -->
                        <div>
                            <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="apartment">
                                Apartment, suite, etc. <span class="text-[#99674d]">(optional)</span>
                            </label>
                            <input
                                    class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                    id="apartment"
                                    formControlName="apartment"
                                    placeholder="Apartment, suite, etc."
                            />
                        </div>

                        <!-- City & Country -->
                        <div class="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-7">
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="city">City</label>
                                <input
                                        class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('city')"
                                        id="city"
                                        formControlName="city"
                                        placeholder="Anytown"
                                />
                                <p class="error-message" [class.hidden]="!isFieldInvalid('city')">
                                    {{ getFieldError('city') }}
                                </p>
                            </div>
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5"
                                       for="country">Country</label>
                                <select
                                        class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('country')"
                                        id="country"
                                        formControlName="country"
                                >
                                    <option>United States</option>
                                    <option>Canada</option>
                                    <option>United Kingdom</option>
                                    <option>Vietnam</option>
                                </select>
                                <p class="error-message" [class.hidden]="!isFieldInvalid('country')">
                                    {{ getFieldError('country') }}
                                </p>
                            </div>
                        </div>

                        <!-- State & ZIP -->
                        <div class="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-7">
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="state">State /
                                    Province</label>
                                <input
                                        class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('state')"
                                        id="state"
                                        formControlName="state"
                                        placeholder="CA"
                                />
                                <p class="error-message" [class.hidden]="!isFieldInvalid('state')">
                                    {{ getFieldError('state') }}
                                </p>
                            </div>
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="zip-code">ZIP /
                                    Postal Code</label>
                                <input
                                        class="input-field w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('zipCode')"
                                        id="zip-code"
                                        formControlName="zipCode"
                                        placeholder="90210"
                                />
                                <p class="error-message" [class.hidden]="!isFieldInvalid('zipCode')">
                                    {{ getFieldError('zipCode') }}
                                </p>
                            </div>
                        </div>

                        <!-- Phone -->
                        <div>
                            <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="phone">
                                Phone <span class="text-[#99674d]">(for shipping updates)</span>
                            </label>
                            <div class="relative">
                                <input
                                        class="input-field pl-12 w-full border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        id="phone"
                                        formControlName="phone"
                                        placeholder="(555) 123-4567"
                                        type="tel"
                                />
                                <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">phone</span>
                            </div>
                        </div>
                    </div>

                    <!-- Save Address Checkbox -->
                    <div class="mt-8 flex items-center gap-3">
                        <input
                                class="form-checkbox h-5 w-5 text-[#eb6c28] border-[#f3ebe7] rounded focus:ring-[#eb6c28] transition-colors"
                                id="save-address"
                                formControlName="saveAddress"
                                type="checkbox"
                        />
                        <label class="text-base text-[#1b120e]" for="save-address">Save this information for next
                            time</label>
                    </div>
                </div>
            </section>

            <!-- Payment Method Section -->
            <section class="section-card space-y-8 relative">
                <div class="absolute -bottom-4 -right-4 w-20 h-20 bg-[#eb6c28]/20 rounded-full opacity-40 blur-xl -z-10 animate-pulse delay-500"></div>

                <h2 class="title-text text-[#1b120e] text-2xl font-bold leading-tight flex items-center gap-2.5">
                    <span class="material-icons-outlined text-3xl text-[#eb6c28]">payment</span>
                    Payment Method
                </h2>
                <p class="text-base text-[#99674d]">All transactions are secure and encrypted with 256-bit SSL
                    technology.</p>

                <div class="space-y-6">
                    <!-- Credit Card Payment -->
                    <label class="payment-option flex items-start gap-5 rounded-2xl border border-solid border-[#f3ebe7] p-6 has-[:checked]:border-[#eb6c28] has-[:checked]:bg-[#fcf9f8] cursor-pointer transition-all duration-300 hover:border-[#eb6c28] hover:shadow-lg">
                        <input
                                class="form-radio mt-1 text-[#eb6c28] focus:ring-[#eb6c28]"
                                name="paymentMethod"
                                type="radio"
                                value="creditCard"
                                [checked]="selectedPaymentMethod === 'creditCard'"
                                (change)="onPaymentMethodChange('creditCard')"
                        />
                        <div class="flex-1">
                            <span class="text-[#1b120e] text-lg font-semibold">Credit or debit card</span>
                            <div class="mt-2 flex items-center gap-2">
                                <img alt="Visa" class="h-8 rounded-md shadow-sm transition-transform hover:scale-105"
                                     src="https://lh3.googleusercontent.com/aida-public/AB6AXuASVuv1glg5ZEVAly7wj4RTWrC42sFUYjz2Vj1LHZMPSrkNufrj5wbfsNGJKPzIzx9BpplMUxc38oADrbOCkeSMKy_WqhDLuMaTh3HcCAobBDUgewY9ZyeB01L--qcR4761TGTtxsM61ILYo3ekJ8Tad4tX6eQnaJLJsdcPfl-QF0KD1MrWUUsGlgF6yWPxZOZbKXbvbvyOY_j6R0-xgSKeqS3dNdVC-s7bmeFOJrNqKcsn5d4Xfch4ngD1Bkokh2exTgvtwEmpf08"/>
                                <img alt="Mastercard"
                                     class="h-8 rounded-md shadow-sm transition-transform hover:scale-105"
                                     src="https://lh3.googleusercontent.com/aida-public/AB6AXuASCrXq-vwoeVlCE-PRt2CdKlkWGThG0ks06w97mubGcKIqOGFOUuSitORoA3JzyAVnEGgXB3t7SfG4appsM_R2yON7z9uxmVrRw-72EU60cxMbyAb7NlIrPvfk5k---VZiURsBpsf-ii52cAiOkXK6fI6eM1GMDxxZNb7eU2P1i37SAfYjeNBLoiKb-dxfdn9ZUU-fES6Vca8o_XRImWLk9OdK1D9b6jGkkVKLVZ8tJYXQJEdJUTJWFYPBS8Qae5Wzgz7yW5KUbqk"/>
                                <img alt="Amex" class="h-8 rounded-md shadow-sm transition-transform hover:scale-105"
                                     src="https://lh3.googleusercontent.com/aida-public/AB6AXuBzplFW6ggySWpXHNEmD-P-P4QH7u3C2h6JZNtdKEoBBywd4--JIrAoJVHEKW_ctysB9DjLyRLETEkZ6Ux354bFmJ0GdhgtpxMEDp4ox_oJpVIBxkbfrRQL0NuakrDgHwBu-hSYF3FnYTrF0ArQ7-bkvqbHSZ5zarnWhd4G1eQghA8vgxjgkgNNf3mnS8x7992mCkUYtVq--U21xF7aNV1v4AAr_Be-HBS6mjI1IKRujTzRpiiSJbhO0blEJB3kKy6Jq3qhFyfL8Lw"/>
                                <img alt="Discover"
                                     class="h-8 rounded-md shadow-sm transition-transform hover:scale-105"
                                     src="https://lh3.googleusercontent.com/aida-public/AB6AXuCWYynFL7LZalqt9BuaNGpY0z9GlfPWTGSyrQc_roly6BUwJ0VL3zx1A2rvBN3_SRojJItBPVHRW5PNtq3l8dvIQVHvoE4FPFRrlCKsOITM1I2fTkfKwor56yNeJona0q-PERaD4j_yuhZbwBqMu_J_VmqqIx97fXFWqFOVufc-OgbnN7MG8LdpOGXKgSd_EKmeQJ98LNha1Icmw0c1poKonVweBqy49lF5TnOaR_It30701ZFTEUIgAbLSFcmYACvl8n5W65CVWVs"/>
                            </div>
                        </div>
                        <span class="material-icons-outlined payment-icon text-4xl text-[#99674d] transition-all duration-300">credit_card</span>
                    </label>

                    <!-- Credit Card Details -->
                    <div class="pl-12 space-y-6" *ngIf="selectedPaymentMethod === 'creditCard'"
                         id="credit-card-details">
                        <!-- Card Number -->
                        <div>
                            <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="card-number">Card
                                number</label>
                            <div class="relative">
                                <input
                                        class="input-field pl-12 border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('cardNumber')"
                                        id="card-number"
                                        formControlName="cardNumber"
                                        placeholder="0000 0000 0000 0000"
                                />
                                <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">payment</span>
                            </div>
                            <p class="error-message" [class.hidden]="!isFieldInvalid('cardNumber')">
                                {{ getFieldError('cardNumber') }}
                            </p>
                        </div>

                        <!-- Expiration & CVV -->
                        <div class="grid grid-cols-1 sm:grid-cols-2 gap-6">
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="expiration-date">Expiration
                                    date</label>
                                <div class="relative">
                                    <input
                                            class="input-field pl-12 border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                            [class.input-error]="isFieldInvalid('expirationDate')"
                                            id="expiration-date"
                                            formControlName="expirationDate"
                                            placeholder="MM / YY"
                                    />
                                    <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">date_range</span>
                                </div>
                                <p class="error-message" [class.hidden]="!isFieldInvalid('expirationDate')">
                                    {{ getFieldError('expirationDate') }}
                                </p>
                            </div>
                            <div>
                                <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="cvv">Security code
                                    (CVV)</label>
                                <div class="relative">
                                    <input
                                            class="input-field pl-12 border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                            [class.input-error]="isFieldInvalid('cvv')"
                                            id="cvv"
                                            formControlName="cvv"
                                            placeholder="123"
                                    />
                                    <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">security</span>
                                </div>
                                <p class="error-message" [class.hidden]="!isFieldInvalid('cvv')">
                                    {{ getFieldError('cvv') }}
                                </p>
                            </div>
                        </div>

                        <!-- Name on Card -->
                        <div>
                            <label class="block text-base font-medium text-[#1b120e] pb-2.5" for="name-on-card">Name on
                                card</label>
                            <div class="relative">
                                <input
                                        class="input-field pl-12 border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                                        [class.input-error]="isFieldInvalid('nameOnCard')"
                                        id="name-on-card"
                                        formControlName="nameOnCard"
                                        placeholder="John M Doe"
                                />
                                <span class="material-icons-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#99674d] text-2xl">person</span>
                            </div>
                            <p class="error-message" [class.hidden]="!isFieldInvalid('nameOnCard')">
                                {{ getFieldError('nameOnCard') }}
                            </p>
                        </div>

                        <!-- Save Card Checkbox -->
                        <div class="flex items-center gap-3">
                            <input
                                    class="form-checkbox h-5 w-5 text-[#eb6c28] border-[#f3ebe7] rounded focus:ring-[#eb6c28] transition-colors"
                                    id="save-card"
                                    formControlName="saveCard"
                                    type="checkbox"
                            />
                            <label class="text-base text-[#1b120e]" for="save-card">Save card for future
                                purchases</label>
                        </div>
                    </div>

                    <!-- Stripe Payment -->
                    <label class="payment-option flex items-start gap-5 rounded-2xl border border-solid border-[#f3ebe7] p-6 has-[:checked]:border-[#eb6c28] has-[:checked]:bg-[#fcf9f8] cursor-pointer transition-all duration-300 hover:border-[#eb6c28] hover:shadow-lg">
                        <input
                                class="form-radio mt-1 text-[#eb6c28] focus:ring-[#eb6c28]"
                                name="paymentMethod"
                                type="radio"
                                value="stripe"
                                [checked]="selectedPaymentMethod === 'stripe'"
                                (change)="onPaymentMethodChange('stripe')"
                        />
                        <div class="flex-1">
                            <span class="text-[#1b120e] text-lg font-semibold">Stripe Payment</span>
                            <p class="text-sm text-[#99674d] mt-1">Secure payment processing</p>
                        </div>
                        <span class="material-icons-outlined payment-icon text-4xl text-[#99674d] transition-all duration-300">account_balance_wallet</span>
                    </label>

                    <!-- Cash on Delivery -->
                    <label class="payment-option flex items-start gap-5 rounded-2xl border border-solid border-[#f3ebe7] p-6 has-[:checked]:border-[#eb6c28] has-[:checked]:bg-[#fcf9f8] cursor-pointer transition-all duration-300 hover:border-[#eb6c28] hover:shadow-lg">
                        <input
                                class="form-radio mt-1 text-[#eb6c28] focus:ring-[#eb6c28]"
                                name="paymentMethod"
                                type="radio"
                                value="cod"
                                [checked]="selectedPaymentMethod === 'cod'"
                                (change)="onPaymentMethodChange('cod')"
                        />
                        <div class="flex-1">
                            <span class="text-[#1b120e] text-lg font-semibold">Cash on Delivery</span>
                            <p class="text-sm text-[#99674d] mt-1">Pay when your order arrives</p>
                        </div>
                        <span class="material-icons-outlined payment-icon text-4xl text-[#99674d] transition-all duration-300">local_shipping</span>
                    </label>
                </div>

                <!-- Payment Method Messages -->
                <div class="pt-6 text-[#99674d] text-base font-medium" *ngIf="selectedPaymentMethod === 'cod'">
                    You will pay when your order is delivered.
                </div>
                <div class="pt-6 text-[#99674d] text-base font-medium" *ngIf="selectedPaymentMethod === 'stripe'">
                    You will be redirected to Stripe to complete your payment securely.
                </div>
            </section>

            <!-- Mobile Return to Cart -->
            <div class="mt-10 lg:hidden">
                <a routerLink="/cart"
                   class="text-base font-semibold text-[#1b120e] hover:underline transition-colors group flex items-center justify-center gap-1.5 mx-auto">
                    <span class="material-icons-outlined text-xl transform transition-transform duration-300 group-hover:-translate-x-1">arrow_circle_left</span>
                    Return to Cart
                </a>
                <p class="text-sm text-[#99674d] mt-2 text-center">Need to make changes? Go back to your cart.</p>
            </div>
        </form>

        <!-- Order Summary Sidebar -->
        <aside class="w-full lg:w-2/5 space-y-10 lg:sticky lg:top-36">
            <section class="section-card space-y-6 relative">
                <div class="absolute -top-5 -right-5 w-24 h-24 bg-[#eb6c28]/20 rounded-full opacity-30 blur-2xl -z-10 animate-blob"></div>
                <h2 class="title-text text-[#1b120e] text-2xl font-bold leading-tight flex items-center gap-2.5">
                    <span class="material-icons-outlined text-3xl text-[#eb6c28]">shopping_cart</span>
                    Order Summary
                </h2>
                <a routerLink="/cart"
                   class="text-base font-semibold text-[#eb6c28] hover:underline transition-colors lg:hidden absolute top-6 right-6">Edit
                    Cart</a>


                <!-- Gift Card / Discount Code -->
                <div>
                    <label for="discount-code" class="block text-sm font-medium text-[#1b120e] mb-1">Gift card or
                        discount code</label>
                    <div class="flex space-x-2">
                        <input type="text" id="discount-code" [(ngModel)]="discountCode" name="discountCode"
                               class="input-field flex-grow border-[#f3ebe7] focus:border-[#eb6c28] focus:ring-[#eb6c28]"
                               placeholder="Enter code">
                        <button type="button" (click)="applyDiscount()"
                                class="btn whitespace-nowrap bg-[#eb6c28] text-white hover:bg-[#d35400] px-4 py-2 rounded-md font-semibold">
                            Apply
                        </button>
                    </div>
                    <p *ngIf="discountMessage" class="mt-2 text-sm p-3 rounded-md"
                       [ngClass]="{'bg-green-100 text-green-700': discountAppliedSuccessfully, 'bg-red-100 text-red-700': !discountAppliedSuccessfully}">
                        {{ discountMessage }}
                    </p>
                </div>

                <div class="space-y-6">
                    <!-- Dynamic Order Items from CartService -->
                    <div *ngFor="let item of cartItems" class="flex items-center gap-4 p-4 bg-[#f3ebe7] rounded-xl">
                        <div class="w-16 h-16 bg-gradient-to-br from-[#eb6c28]/20 to-[#99674d]/20 rounded-lg flex items-center justify-center">
                            <img *ngIf="item.product.imageLink" [src]="item.product.imageLink" alt="{{ item.product.name }}" class="w-12 h-12 object-contain rounded-md">
                            <span *ngIf="!item.product.imageLink" class="material-icons text-[#eb6c28]">shopping_bag</span>
                        </div>
                        <div class="flex-1">
                            <!-- Product brand -->
                            <p class="text-slate-500 text-sm">{{ item.product.brandName }}</p>
                            <!-- Product name -->
                            <h3 class="font-semibold text-[#1b120e]">{{ item.product.name }}</h3>
                            <p class="text-sm text-[#99674d]">Quantity: {{ item.quantity }}</p>
                        </div>
                        <span class="font-semibold text-[#1b120e]">{{ item.totalPrice | currency:'VND':'symbol':'1.0-0' }}</span>
                    </div>

                    <!-- Order Total -->
                    <div class="border-t border-[#f3ebe7] pt-4 space-y-2">
                        <div class="flex justify-between text-[#99674d]">
                            <span>Items ({{ getItemCount() }}):</span>
                            <span>{{ itemsTotal | currency:'VND':'symbol':'1.0-0' }}</span>
                        </div>
                        <div class="flex justify-between text-[#99674d]">
                            <span>Shipping & handling:</span>
                            <span>{{ shippingAndHandling | currency:'VND':'symbol':'1.0-0' }}</span>
                        </div>
                        <div class="flex justify-between text-[#99674d]" *ngIf="discountAmount > 0">
                            <span>Discount:</span>
                            <span class="text-red-500">-{{ discountAmount | currency:'VND':'symbol':'1.0-0' }}</span>
                        </div>
                        <div class="flex justify-between text-[#1b120e] font-medium">
                            <span>Total before tax:</span>
                            <span>{{ totalBeforeTax | currency:'VND':'symbol':'1.0-0' }}</span>
                        </div>
                        <div class="flex justify-between text-[#99674d]">
                            <span>Estimated tax:</span>
                            <span>{{ estimatedTax | currency:'VND':'symbol':'1.0-0' }}</span>
                        </div>
                        <div class="flex justify-between text-xl font-semibold text-[#eb6c28] border-t border-[#f3ebe7] pt-3 mt-3">
                            <span>Order total:</span>
                            <span>{{ orderTotal | currency:'VND':'symbol':'1.0-0' }}</span>
                        </div>
                    </div>
                </div>
            </section>

            <!-- Place Order Button & Terms -->
            <section class="section-card space-y-4">
                <button type="button" (click)="onSubmit()"
                        class="btn w-full bg-[#eb6c28] text-white hover:bg-[#d35400] font-bold text-lg py-3 rounded-md">
                    Place your order - {{ orderTotal | currency:'VND':'symbol':'1.0-0' }}
                    <span class="material-icons-outlined ml-2 align-middle">rocket_launch</span>
                </button>
